public class BasicDeserializerFactory__addExplicitAnyCreator_TriageGen1Test {

    private TestableBasicDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private CreatorCollector creators;

    // Subclass to expose protected method and handle constructor
    private static class TestableBasicDeserializerFactory extends BasicDeserializerFactory {
        protected TestableBasicDeserializerFactory() {
            super(null);
        }

        @Override
        public void _addExplicitAnyCreator(DeserializationContext ctxt,
                                          BeanDescription beanDesc,
                                          CreatorCollector creators,
                                          CreatorCandidate candidate) throws JsonMappingException {
            super._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);
        }

        // Mocking the internal helper methods called by the target method
        @Override
        protected void _addExplicitDelegatingCreator(DeserializationContext ctxt, BeanDescription beanDesc, CreatorCollector creators, CreatorCandidate candidate) {
            creators.addDelegatingCreator(candidate.creator());
        }

        @Override
        protected void _addExplicitPropertyCreator(DeserializationContext ctxt, BeanDescription beanDesc, CreatorCollector creators, CreatorCandidate candidate) {
            creators.addPropertyCreator(candidate.creator(), false, null);
        }

        @Override
        protected boolean _handleSingleArgumentCreator(CreatorCollector creators, AnnotatedWithParams ctor, boolean isCreator, boolean isVisible) {
            creators.addCreator(ctor);
            return true;
        }

        @Override
        protected SettableBeanProperty constructCreatorProperty(DeserializationContext ctxt, BeanDescription beanDesc, PropertyName name, int index, AnnotatedParameter param, JacksonInject.Value injectable) {
            return mock(SettableBeanProperty.class);
        }
    }

    @Before
    public void setUp() {
        factory = new TestableBasicDeserializerFactory();
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        creators = mock(CreatorCollector.class);
    }

    /**
     * Case 1: Multi-parameter creator (paramCount != 1)
     * Subcase A: Has one non-injected param without name -> Delegating
     * Subcase B: Otherwise -> Property Creator
     */
    @Test
    public void testMultiParamCreator_Delegating() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);

        when(candidate.paramCount()).thenReturn(2);
        when(candidate.findOnlyParamWithoutInjection()).thenReturn(0);
        when(candidate.paramName(0)).thenReturn(null);
        when(candidate.creator()).thenReturn(creator);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addDelegatingCreator(creator);
    }

    @Test
    public void testMultiParamCreator_Property() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);

        when(candidate.paramCount()).thenReturn(2);
        when(candidate.findOnlyParamWithoutInjection()).thenReturn(-1);
        when(candidate.creator()).thenReturn(creator);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addPropertyCreator(eq(creator), eq(false), any());
    }

    /**
     * Case 2: Single parameter creator (paramCount == 1)
     * Subcase A: Has explicit name or injection -> Property Creator
     * Subcase B: No explicit name/injection, but has propertyDef and implicit name matches -> Property Creator
     * Subcase C: Standard single arg -> handleSingleArgumentCreator
     */
    @Test
    public void testSingleParamCreator_WithExplicitName() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        PropertyName propName = new PropertyName("test");

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.explicitParamName(0)).thenReturn(propName);
        when(candidate.creator()).thenReturn(creator);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addPropertyCreator(eq(creator), eq(true), any(SettableBeanProperty[].class));
    }

    @Test
    public void testSingleParamCreator_WithInjection() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        JacksonInject.Value injectValue = mock(JacksonInject.Value.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.injection(0)).thenReturn(injectValue);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.creator()).thenReturn(creator);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addPropertyCreator(eq(creator), eq(true), any(SettableBeanProperty[].class));
    }

    @Test
    public void testSingleParamCreator_ImplicitNameMatchesProperty() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);
        PropertyName implicitName = new PropertyName("id");

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.propertyDef(0)).thenReturn(propDef);
        when(candidate.findImplicitParamName(0)).thenReturn(implicitName);
        when(propDef.couldSerialize()).thenReturn(true);
        when(candidate.creator()).thenReturn(creator);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addPropertyCreator(eq(creator), eq(true), any(SettableBeanProperty[].class));
    }

    @Test
    public void testSingleParamCreator_StandardSingleArg() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);
        POJOPropertyBuilder builder = mock(POJOPropertyBuilder.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.propertyDef(0)).thenReturn(propDef);
        when(candidate.creator()).thenReturn(creator);

        // Mocking the cast to POJOPropertyBuilder
        // Since we can't easily mock the cast of a mock, we ensure the mock behaves correctly
        // In a real scenario, propDef would be a POJOPropertyBuilder
        // We use a real instance or a very specific mock
        POJOPropertyBuilder realBuilder = new POJOPropertyBuilder(mock(AnnotatedMember.class));
        when(candidate.propertyDef(0)).thenReturn(realBuilder);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        // Verify handleSingleArgumentCreator was called
        verify(creators).addCreator(creator);
        // Verify removeConstructors was called on the builder
        // (implicitly verified by not crashing and logic flow)
    }

    @Test
    public void testSingleParamCreator_NoImplicitMatch_RemovesConstructors() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);

        // We need a real POJOPropertyBuilder to test the cast and removeConstructors call
        AnnotatedMember member = mock(AnnotatedMember.class);
        POJOPropertyBuilder builder = new POJOPropertyBuilder(member);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.propertyDef(0)).thenReturn(builder);
        when(candidate.creator()).thenReturn(creator);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addCreator(creator);
    }
}
